<template>
  <view class="page" :style="themeStyle">
    <view class="shell" :style="shellStyle">
      <view class="topbar"><button class="back" @tap="goBack">‹</button><view><text class="kicker">TEMPLATE COMMUNITY</text><text class="title">模板广场</text></view></view>
      <view class="search"><text>⌕</text><input v-model="keyword" placeholder="搜索模板名称、简介或标签" maxlength="50" confirm-type="search" @confirm="searchPosts" /><text @tap="searchPosts">搜索</text></view>
      <view class="tabs"><view :class="{active:scope==='all'}" @tap="changeScope('all')">全部分享</view><view :class="{active:scope==='favorites'}" @tap="changeScope('favorites')">我的收藏</view></view>
      <view v-if="loading&&!posts.length" class="empty">正在加载分享…</view>
      <view v-else-if="error&&!posts.length" class="empty" @tap="load">{{ error }} · 点击重试</view>
      <view v-else-if="!posts.length" class="empty">{{ scope==='favorites'?'还没有收藏的模板':'暂无用户分享' }}</view>
      <view v-else class="post-list"><view v-for="post in posts" :key="post.id" class="post-card">
        <view class="author"><view class="avatar"><image v-if="post.authorAvatarUrl" :src="post.authorAvatarUrl" mode="aspectFill" /><text v-else>{{ initial(post.authorName) }}</text></view><text>{{ post.authorName||'训练伙伴' }}</text><text class="post-date">{{ dateText(post.createdAt) }}</text></view>
        <view class="post-content"><text class="post-title">{{ post.title }}</text><text class="post-description">{{ post.description||'分享了一份训练安排' }}</text><view class="tags"><text v-for="tag in post.tags" :key="tag">#{{ tag }}</text></view></view>
        <view class="post-footer"><view class="stats"><text>☆ {{ post.favoriteCount }}</text><text>♥ {{ post.likeCount }}</text><text>⇩ {{ post.downloadCount }}</text></view><text class="detail-link" @tap="openDetail(post)">模板详情 ›</text></view>
      </view></view>
      <button v-if="hasMore" class="more" :disabled="loading" @tap="loadMore">{{ loading?'加载中…':'加载更多' }}</button>
      <button class="mine-button" @tap="openMine">我发布的帖子 ›</button>
    </view>

    <view v-if="detail" class="overlay" @tap="detail=null"><view class="dialog" @tap.stop>
      <view class="dialog-head"><button class="modal-back" @tap="detail=null">‹</button><view><text class="dialog-kicker">TEMPLATE DETAILS</text><text class="dialog-title">{{ detail.title }}</text><text class="dialog-sub">{{ detail.authorName }} · {{ detail.partCount }} 个部位 · {{ detail.actionCount }} 个动作</text></view></view>
      <scroll-view scroll-y class="dialog-scroll"><text class="description">{{ detail.description||'作者没有填写简介' }}</text><view class="tags"><text v-for="tag in detail.tags" :key="tag">#{{ tag }}</text></view><view v-for="(action,index) in detail.exercises" :key="index" class="action-row"><text>{{ index+1 }}. {{ action.exerciseName||'系统动作' }}</text><text>{{ partName(action.bodyPart) }}{{ action.variantName?' · '+action.variantName:'' }} · {{ action.plannedSets }} 组</text><text>{{ targetText(action) }}</text></view></scroll-view>
      <view class="detail-actions"><view class="reaction" :class="{active:detail.favorited}" @tap="react('favorite')"><text>☆</text><text>收藏 {{ detail.favoriteCount }}</text><view v-if="starBurst" class="star-burst"><text v-for="n in 7" :key="n">★</text></view></view><view class="reaction" :class="{active:detail.liked}" @tap="react('like')"><text>♥</text><text>点赞 {{ detail.likeCount }}</text></view><button class="import" :disabled="importing" @tap="importPost">{{ importing?'导入中…':'导入我的模板' }}</button></view>
    </view></view>

    <view v-if="mineVisible" class="overlay"><view class="dialog mine-dialog"><view class="dialog-head"><button class="modal-back" @tap="mineVisible=false">‹</button><view><text class="dialog-kicker">MY POSTS</text><text class="dialog-title">我发布的帖子</text><text class="dialog-sub">已下载的用户副本不会随帖子删除</text></view></view><scroll-view scroll-y class="dialog-scroll"><view v-if="!myPosts.length" class="empty">还没有发布过模板</view><view v-for="post in myPosts" :key="post.id" class="mine-row"><view @tap="openMineDetail(post)"><text>{{ post.title }}</text><text>{{ dateText(post.createdAt) }} · {{ post.downloadCount }} 次导入</text></view><text @tap="removePost(post)">删除</text></view></scroll-view></view></view>
  </view>
</template>

<script setup>
import{computed,ref}from'vue'
import{onShow}from'@dcloudio/uni-app'
import{pageSafeTop}from'../../utils/page-safe-area'
import{deleteCommunityTemplate,getCommunityTemplate,importCommunityTemplate,listCommunityTemplates,setCommunityReaction}from'../../api/templates'
import{bodyPartName,recordMethodName}from'../../constants/exercise-meta'
const themes=[{accent:'#7775bd',accent2:'#a59bd2',pale:'#f1f0f9',pale2:'#faf9fd',glow:'119,117,189'},{accent:'#5f9fa5',accent2:'#8bbdaf',pale:'#edf6f5',pale2:'#f8fbfa',glow:'95,159,165'},{accent:'#bd8073',accent2:'#cda56f',pale:'#faf1ed',pale2:'#fdf9f5',glow:'189,128,115'}]
const themeIndex=ref(0),posts=ref([]),myPosts=ref([]),loading=ref(false),error=ref(''),keyword=ref(''),query=ref(''),scope=ref('all'),page=ref(1),hasMore=ref(false)
const detail=ref(null),mineVisible=ref(false),importing=ref(false),reacting=ref(false),starBurst=ref(false)
function getShellStyle(){
  // #ifdef MP-WEIXIN
  const system=uni.getSystemInfoSync(),statusBarHeight=Number(system?.statusBarHeight)||0
  const capsule=uni.getMenuButtonBoundingClientRect?.(),top=Number(capsule?.top),bottom=Number(capsule?.bottom)
  const gap=Number.isFinite(top)&&top>statusBarHeight?Math.max(8,top-statusBarHeight):10
  return{paddingTop:`${Math.ceil(Number.isFinite(bottom)&&bottom>statusBarHeight?bottom+gap:statusBarHeight+54)}px`}
  // #endif
  return{}
}
const shellStyle=ref(getShellStyle())
const overlaySafeTop=pageSafeTop()
const themeStyle=computed(()=>{const t=themes[themeIndex.value];return{'--accent':t.accent,'--accent-2':t.accent2,'--pale':t.pale,'--pale-2':t.pale2,'--glow-rgb':t.glow,'--page-safe-top':`${overlaySafeTop}px`}})
const initial=name=>Array.from(name||'训')[0]||'训'
const partName=bodyPartName
const dateText=value=>String(value||'').slice(0,10).replaceAll('-','/')
const targetText=action=>(action.recordMethods||[]).map(method=>`${recordMethodName(method)} ${action.targetMetrics?.[method]??'—'}`).join(' · ')
async function load(reset=true){if(loading.value)return;loading.value=true;error.value='';try{const next=reset?1:page.value+1;const result=await listCommunityTemplates({q:query.value,scope:scope.value,page:next,pageSize:20});posts.value=reset?result.items||[]:[...posts.value,...(result.items||[])];page.value=next;hasMore.value=Boolean(result.hasMore)}catch(cause){error.value=cause.message||'加载失败';if(!reset)uni.showToast({title:error.value,icon:'none'})}finally{loading.value=false}}
function loadMore(){load(false)}
function searchPosts(){query.value=keyword.value.trim();load()}
function changeScope(value){if(scope.value===value)return;scope.value=value;posts.value=[];load()}
async function openDetail(post){try{detail.value=await getCommunityTemplate(post.id)}catch(cause){uni.showToast({title:cause.message||'帖子读取失败',icon:'none'})}}
function updatePost(value){const index=posts.value.findIndex(item=>item.id===value.id);if(index>=0)posts.value[index]=value;detail.value=value;if(scope.value==='favorites'&&!value.favorited)posts.value=posts.value.filter(item=>item.id!==value.id)}
async function react(kind){if(reacting.value||!detail.value)return;const post=detail.value,enabled=kind==='favorite'?!post.favorited:!post.liked;reacting.value=true;try{const updated=await setCommunityReaction(post.id,kind,enabled);updatePost(updated);if(kind==='favorite'&&enabled){starBurst.value=true;setTimeout(()=>starBurst.value=false,800)}}catch(cause){uni.showToast({title:cause.message||'操作失败',icon:'none'})}finally{reacting.value=false}}
async function importPost(){if(importing.value||!detail.value)return;importing.value=true;try{await importCommunityTemplate(detail.value.id);detail.value={...detail.value,downloadCount:detail.value.downloadCount+1};const index=posts.value.findIndex(item=>item.id===detail.value.id);if(index>=0)posts.value[index]=detail.value;uni.showModal({title:'导入成功',content:'已复制到“我的模板”，相关系统动作也已加入你的动作库。',cancelText:'留在广场',confirmText:'查看我的模板',success:result=>{if(result.confirm){detail.value=null;uni.navigateTo({url:'/pages/my-templates/my-templates'})}}})}catch(cause){uni.showToast({title:cause.message||'导入失败',icon:'none'})}finally{importing.value=false}}
async function openMine(){try{const items=[];let next=1;for(;;){const result=await listCommunityTemplates({scope:'mine',page:next,pageSize:30});items.push(...result.items);if(!result.hasMore)break;next++}myPosts.value=items;mineVisible.value=true}catch(cause){uni.showToast({title:cause.message||'帖子读取失败',icon:'none'})}}
function openMineDetail(post){mineVisible.value=false;openDetail(post)}
function removePost(post){uni.showModal({title:'删除这篇帖子？',content:'帖子将从广场消失，其他用户已导入的模板仍会保留。',success:async result=>{if(!result.confirm)return;try{await deleteCommunityTemplate(post.id);myPosts.value=myPosts.value.filter(item=>item.id!==post.id);posts.value=posts.value.filter(item=>item.id!==post.id);uni.showToast({title:'帖子已删除',icon:'success'})}catch(cause){uni.showToast({title:cause.message||'删除失败',icon:'none'})}}})}
function goBack(){uni.navigateBack({fail:()=>uni.redirectTo({url:'/pages/training-plan/training-plan'})})}
onShow(()=>{const index=Number(uni.getStorageSync('fit_note_theme_index'));themeIndex.value=themes[index]?index:0;load()})
</script>

<style scoped>
.page{min-height:100vh;box-sizing:border-box;color:#30374a;background:linear-gradient(145deg,var(--pale),var(--pale-2))}.shell{padding:calc(var(--status-bar-height) + 28rpx) 28rpx calc(60rpx + env(safe-area-inset-bottom));box-sizing:border-box}.topbar{display:flex;align-items:center;gap:18rpx}.back,.modal-back{width:64rpx;height:64rpx;flex:none;margin:0;padding:0;border:0;border-radius:20rpx;color:var(--accent);background:#fff;font-size:43rpx;line-height:58rpx}.back:after,.modal-back:after,button:after{border:0}.kicker,.title{display:block}.kicker{color:var(--accent);font-size:16rpx;letter-spacing:3rpx;font-weight:700}.title{font-size:31rpx;font-weight:760}.search{display:flex;align-items:center;gap:13rpx;height:79rpx;margin:28rpx 0 18rpx;padding:0 18rpx;border:1rpx solid rgba(var(--glow-rgb),.15);border-radius:22rpx;background:#fff}.search>text:first-child{color:var(--accent);font-size:32rpx}.search>text:last-child{color:var(--accent);font-size:18rpx;font-weight:700}.search input{flex:1;min-width:0;font-size:18rpx}.tabs{display:flex;gap:12rpx;margin-bottom:20rpx}.tabs view{padding:12rpx 18rpx;border-radius:16rpx;color:#8790a1;background:#fff;font-size:18rpx}.tabs view.active{color:#fff;background:var(--accent)}.post-list{display:grid;gap:17rpx}.post-card{padding:22rpx;border:1rpx solid rgba(255,255,255,.9);border-radius:28rpx;background:rgba(255,255,255,.86);box-shadow:0 17rpx 36rpx rgba(51,59,83,.06)}.author{display:flex;align-items:center;gap:12rpx;color:#596174;font-size:17rpx;font-weight:700}.avatar{display:grid;place-items:center;flex:none;width:51rpx;height:51rpx;overflow:hidden;border-radius:50%;color:#fff;background:linear-gradient(135deg,var(--accent),var(--accent-2))}.avatar image{width:100%;height:100%}.post-date{margin-left:auto;color:#a1a6b1;font-size:14rpx;font-weight:400}.post-content{min-height:130rpx;padding:17rpx 0 13rpx}.post-title,.post-description{display:block}.post-title{font-size:25rpx;font-weight:780}.post-description{display:-webkit-box;overflow:hidden;margin-top:9rpx;color:#747c8e;font-size:17rpx;line-height:1.55;-webkit-line-clamp:2;-webkit-box-orient:vertical}.tags{display:flex;flex-wrap:wrap;gap:8rpx;margin-top:12rpx}.tags text{padding:6rpx 10rpx;border-radius:10rpx;color:var(--accent);background:var(--pale);font-size:14rpx}.post-footer{display:flex;align-items:center;justify-content:space-between;gap:10rpx;padding-top:15rpx;border-top:1rpx solid rgba(var(--glow-rgb),.11)}.stats{display:flex;gap:12rpx;color:#939aa7;font-size:15rpx}.detail-link{color:var(--accent);font-size:16rpx;font-weight:730}.empty{padding:110rpx 15rpx;color:#9ca2af;font-size:19rpx;text-align:center}.more,.mine-button{width:100%;height:69rpx;margin-top:20rpx;border:0;border-radius:20rpx;color:var(--accent);background:#fff;font-size:18rpx;line-height:69rpx}.mine-button{margin-top:29rpx;background:var(--pale-2);font-weight:720}.overlay{position:fixed;z-index:20;inset:0;display:flex;align-items:flex-end;justify-content:center;background:rgba(30,34,49,.5)}.dialog{display:flex;flex-direction:column;width:100%;max-height:88vh;box-sizing:border-box;padding:23rpx 26rpx calc(24rpx + env(safe-area-inset-bottom));border-radius:32rpx 32rpx 0 0;background:#fcfcff}.dialog-head{display:flex;align-items:center;gap:14rpx;min-height:66rpx}.dialog-head>view{min-width:0}.dialog-title,.dialog-sub{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.dialog-title{font-size:27rpx;font-weight:800}.dialog-sub{margin-top:4rpx;color:#9aa0ad;font-size:15rpx}.dialog-scroll{flex:1;min-height:0;max-height:64vh;margin-top:17rpx}.description{display:block;color:#687183;font-size:18rpx;line-height:1.6}.action-row{display:grid;gap:7rpx;margin:13rpx 0;padding:18rpx;border-radius:18rpx;background:var(--pale-2);color:#828a9a;font-size:15rpx}.action-row text:first-child{color:#424b5d;font-size:19rpx;font-weight:750}.detail-actions{display:flex;align-items:center;gap:8rpx;margin-top:18rpx}.reaction{position:relative;display:grid;justify-items:center;gap:3rpx;min-width:84rpx;color:#9ca3b0;font-size:13rpx}.reaction>text:first-child{font-size:29rpx}.reaction.active{color:var(--accent)}.import{flex:1;height:68rpx;margin:0;border:0;border-radius:19rpx;color:#fff;background:linear-gradient(100deg,var(--accent),var(--accent-2));font-size:18rpx;font-weight:750;line-height:68rpx}.star-burst{position:absolute;top:-5rpx;left:50%;pointer-events:none}.star-burst text{position:absolute;color:var(--accent);font-size:18rpx;animation:scatter .8s ease-out both}.star-burst text:nth-child(1){--x:-55rpx;--y:-55rpx}.star-burst text:nth-child(2){--x:-24rpx;--y:-75rpx}.star-burst text:nth-child(3){--x:17rpx;--y:-68rpx}.star-burst text:nth-child(4){--x:54rpx;--y:-44rpx}.star-burst text:nth-child(5){--x:-58rpx;--y:9rpx}.star-burst text:nth-child(6){--x:63rpx;--y:14rpx}.star-burst text:nth-child(7){--x:0rpx;--y:-88rpx}@keyframes scatter{from{opacity:1;transform:translate(0,0) scale(.5)}to{opacity:0;transform:translate(var(--x),var(--y)) scale(1.3)}}.mine-row{display:flex;justify-content:space-between;align-items:center;gap:15rpx;margin:10rpx 0;padding:18rpx;border-radius:17rpx;background:var(--pale-2)}.mine-row>view{flex:1;min-width:0}.mine-row>view text{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.mine-row>view text:first-child{font-size:19rpx;font-weight:750}.mine-row>view text:last-child{margin-top:5rpx;color:#939aa7;font-size:14rpx}.mine-row>text{color:#bc6972;font-size:17rpx}@media(min-width:900px){.shell{max-width:760px;margin:auto;padding-top:34px}.dialog{width:620px;max-height:82vh;border-radius:26px;padding:24px}}
.dialog-kicker{display:block;color:var(--accent);font-size:14rpx;font-weight:750;letter-spacing:2rpx}
.overlay{box-sizing:border-box;padding-top:calc(var(--page-safe-top) + 12rpx)}.dialog{max-height:calc(100vh - var(--page-safe-top) - 12rpx)}
</style>
